def icon_uri(host):
    """Cached favicon of a site as a data: URI (empty string if we don't have one)."""
    if host and re.fullmatch(r"[\w.\-]+", host):
        ip = ICON_DIR / (host + ".png")
        if ip.exists():
            try:
                return "data:image/png;base64," + base64.b64encode(ip.read_bytes()).decode()
            except OSError:
                pass
    return ""


