    def _import_row(self, src):
        row = TourRowCard()
        row.setFixedHeight(56)
        h = QHBoxLayout(row)
        h.setContentsMargins(16, 0, 12, 0)
        h.setSpacing(12)
        col = QVBoxLayout()
        col.setSpacing(0)
