        if not PRIVATE:
            m.addAction("Add page to Essentials", lambda: self.add_essential(self.cur()))
        m.addSeparator()
        m.addAction("Bookmarks\tCtrl+Shift+O", self.open_bookmarks)
        m.addAction("History\tCtrl+H", self.open_history)
